    throw std::runtime_error("Failed to compute priority");
    return 42;
}
void cusDel(Widget *ptr) { delete ptr; }

void processWidget(std::shared_ptr<Widget> spw, int priority) { /* ... */ }

void unsafe_call() {
    // DANGEROUS: Potentially leaks Widget if computePriority() throws
    // The evaluation order could be:
    // 1. new Widget
    // 2. computePriority() -> throws!
    // 3. std::shared_ptr constructor is never called, memory is leaked.
    // processWidget(
    //     std::shared_ptr<Widget>(new Widget, cusDel),
    //     computePriority()
    // );
}

void safe_call() {
    // SAFE: Smart pointer is constructed in a separate statement.
    // Ownership is secured before any other code that might throw runs.
    std::shared_ptr<Widget> spw(new Widget, cusDel);
    try {
        // Now, if computePriority throws, spw's destructor will be called during
        // stack unwinding, safely deleting the Widget.
        processWidget(spw, computePriority());
    } catch (const std::runtime_error& e) {
        // Widget is cleaned up automatically, no leak.
    }
}
